digest = _h21.digest
code = _h21.code
functions = _h21.functions
body_of = _h21.body_of
outside_functions = _h21.outside_functions


def snapshot_text(script: str) -> str:
    return (SNAPSHOT / 'src' / script).read_text(encoding='utf-8-sig')


def current_text(script: str) -> str:
    return (ROOT / 'src' / script).read_text(encoding='utf-8-sig')


def round22_diff(script: str, text: str | None = None) -> dict:
    """pre-fix22 snapshot -> now (or `text`) for one script: every function the same, comments only, or declared
    with matching digests; code outside functions the same apart from comments, or exactly the declared lines."""
    old_text = snapshot_text(script)
    new_text = current_text(script) if text is None else text
    old_fns, new_fns = functions(old_text), functions(new_text)
    out = {}
    for fn in sorted(set(old_fns) | set(new_fns)):
        before, now = old_fns.get(fn), new_fns.get(fn)
        if before is None:
            decl = ADDED.get((script, fn))
            assert decl is not None, (script, fn, 'added in round 22 but not declared in ADDED')
            assert digest(now) == decl[1], (script, fn, 'added body differs from the declared one')
            out[fn] = 'added'
        elif now is None:
            decl = REMOVED.get((script, fn))
            assert decl is not None, (script, fn, 'deleted in round 22 but not declared in REMOVED')
            assert digest(before) == decl[1], (script, fn, 'pre-fix22 body is not the one the removal was declared against')
            out[fn] = 'removed'
        elif before == now:
            continue
        elif code(before) == code(now):
            out[fn] = 'comments'
        else:
            decl = CHANGED.get((script, fn))
            assert decl is not None, (script, fn, 'changed in round 22 but not declared in CHANGED')
            assert digest(before) == decl[1], (script, fn, 'pre-fix22 body is not the one the declaration was made against')
            assert digest(now) == decl[2], (script, fn, 'body differs from the declared round-22 change (edited after sealing)')
            out[fn] = 'declared'
    old_lines, new_lines = outside_functions(old_text).splitlines(), outside_functions(new_text).splitlines()
    if old_lines != new_lines:
        decl = PROPERTIES.get(script)
        assert decl is not None, (script, 'code outside functions changed in round 22 but not declared')
        added = tuple(x for x in new_lines if x not in old_lines)
        removed = tuple(x for x in old_lines if x not in new_lines)
        assert (added, removed) == (decl[1], decl[2]), (script, 'lines outside functions differ from the declared ones',
                                                        added, removed)
        out['<properties>'] = 'declared'
    return out


_VERIFIED = None


def verify() -> dict:
    """Every script: whole-file removals / additions by sha256, everything else through round22_diff."""
    global _VERIFIED
    if _VERIFIED is not None:
        return _VERIFIED
    old = {p.name for p in (SNAPSHOT / 'src').glob('*.psc')}
    new = {p.name for p in (ROOT / 'src').glob('*.psc')}
    report = {}
    for name in sorted(old | new):
        if name not in old or name not in new:
            decl = FILES.get(name)
            assert decl is not None, (name, 'script added or removed in round 22 but not declared in FILES')
            path = SNAPSHOT / 'src' / name if name in old else ROOT / 'src' / name
            assert decl[2] == ('removed' if name in old else 'added'), (name, 'declared the other way round')
            assert hashlib.sha256(path.read_bytes()).hexdigest() == decl[1], (name, 'file differs from the declared one')
            report[name] = decl[2]
            continue
        changes = round22_diff(name)
        if changes:
            report[name] = changes
    for (script, fn) in list(CHANGED) + list(REMOVED) + list(ADDED):
        assert script in report and fn in report[script], (script, fn, 'declared but not a round-22 change')
    _VERIFIED = report
    return report


def legacy_source() -> Path:
    """The scripts the verifiers of rounds 6-21 check: the pre-fix22 snapshot, once verify() tied it to today."""
    verify()
    return SNAPSHOT / 'src'


# Silent edits (a number or a call changed inside a declared, an added or an untouched function): each must fail.
SILENT_EDITS = [
    ('ESSBController.psc', 'OnFormClosed', 'BurstCharge = SelfCharge', 'BurstCharge = SelfCharge + 1'),
    ('ESSBController.psc', 'OnESSBJudgment', 'ApplyUtil(1, 60.0, 5, target)', 'ApplyUtil(1, 90.0, 5, target)'),
    ('ESSBElem2.psc', 'JudgeArea', '0.2 * punish', '0.3 * punish'),
    ('ESSBReactions.psc', 'Surge', 'remaining * 1.5', 'remaining * 2.0'),
    ('ESSBGuard.psc', 'OnHitEx', 'Ctl.ApplyUtil(0, 30.0, 3, attacker)', 'Ctl.ApplyUtil(0, 45.0, 3, attacker)'),
]


def self_check() -> dict:
    """Every declaration is true now, and the silent edits are caught."""
    verify()
    faults = []
    for script, fn, old, new in SILENT_EDITS:
        text = current_text(script)
        body = body_of(text, fn)
        assert body is not None and old in body, (script, fn, old)
        mutated = text.replace(body, body.replace(old, new, 1), 1)
        try:
            round22_diff(script, mutated)
        except AssertionError:
            faults.append(f'{script}:{fn}')
            continue
        raise AssertionError(('silent edit not caught', script, fn, old, new))
    return dict(changed=len(CHANGED), removed=len(REMOVED), added=len(ADDED), properties=len(PROPERTIES),
                files=len(FILES), silent_edits_caught=faults)
